//! QML: `qmlls`, Qt's own language server, run against a bare checkout
//! rather than a Qt build tree.
//!
//! `qmlls` resolves imports (`import QtQuick`, and a same-directory
//! component like `Helper { }`) through a build directory that CMake's Qt
//! Quick tooling generates — a `.qmlls.ini` naming it, plus the `qmldir`
//! and `qmltypes` files that build produces. The fixture's `.qmlls.ini`
//! names a `build` directory that does not exist and is not generated by
//! this repository, so the assumption here is that a bare checkout gives
//! `qmlls` no import path at all. If that assumption holds, every probe
//! that depends on resolving `QtObject` or a sibling component
//! (effectively all of them) is expected to fail closed rather than error,
//! which is the "answers nothing" case
//! (`backlog/generic-baseline/answering-is-availability.md`) and not a
//! reason to drop the probes.

use crate::probe::{Candidate, Language, Probe, rename_preview, show, uses};
use crate::report::Outcome;

pub const QML: Language = Language {
    name: "qml",
    fixture: "qml",
    // "qml" is not one of the eleven language ids `src/config.rs` knows, so
    // its extension has to be spelled out here rather than looked up.
    extensions: &["qml"],
    extra_files: &[],
    candidates: CANDIDATES,
    probes: PROBES,
};

const CANDIDATES: &[Candidate] = &[Candidate {
    name: "qmlls",
    argv: &["qmlls"],
    version_argv: &["qmlls", "--version"],
    builtin: false,
}];

const PROBES: &[Probe] = &[
    Probe {
        name: "bare name",
        needs: "workspace/symbol",
        run: |state| {
            let answer = show(state, Some("choose"), None, None);
            Outcome::judge(&answer, |text| {
                text.contains("Helper.qml") && text.contains("function choose(")
            })
        },
    },
    Probe {
        name: "file-scoped name",
        needs: "documentSymbol",
        run: |state| {
            let answer = show(state, Some("identity"), Some("Helper.qml"), None);
            Outcome::judge(&answer, |text| text.contains("function identity("))
        },
    },
    Probe {
        name: "qualified name",
        needs: "outline containers",
        run: |state| {
            let answer = show(state, Some("Config.doubled"), None, None);
            Outcome::judge(&answer, |text| text.contains("function doubled("))
        },
    },
    Probe {
        name: "qualified name, in file",
        needs: "outline nesting",
        run: |state| {
            let answer = show(state, Some("Config.doubled"), Some("Config.qml"), None);
            Outcome::judge(&answer, |text| text.contains("function doubled("))
        },
    },
    Probe {
        name: "cross-file uses",
        needs: "references",
        run: |state| {
            // `choose` is declared in Helper.qml and called from main.qml.
            let answer = uses(state, "choose");
            Outcome::judge(&answer, |text| text.contains("main.qml"))
        },
    },
    Probe {
        name: "anchor to a local",
        needs: "definition at a position",
        run: |state| {
            let answer = show(
                state,
                None,
                Some("main.qml"),
                Some(("var picked = helper.choose(true);", "choose")),
            );
            Outcome::judge(&answer, |text| text.contains("function choose("))
        },
    },
    Probe {
        name: "rename preview",
        needs: "rename WorkspaceEdit",
        run: |state| {
            let answer = rename_preview(state, "choose", "pick");
            Outcome::judge(&answer, |text| {
                text.contains("Helper.qml") && text.contains("main.qml")
            })
        },
    },
    Probe {
        name: "bare name, warm",
        needs: "workspace/symbol after a file is open",
        run: |state| {
            let answer = show(state, Some("choose"), None, None);
            Outcome::judge(&answer, |text| {
                text.contains("Helper.qml") && text.contains("function choose(")
            })
        },
    },
];
